import java.util.*;
import java.util.function.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {

        List<String> cities = Arrays.asList(
            "Mumbai", "Delhi", "Bangalore", "Chennai", "Hyderabad", "Kolkata", "Pune"
        );

        // Try chaining filter + map + sorted + forEach with lambdas!
        System.out.println("Cities with more than 5 characters (uppercase, sorted):");
        cities.stream()
            .filter(c -> c.length() > 5)
            .map(String::toUpperCase)
            .sorted()
            .forEach(System.out::println);

        // Count cities starting with 'M'
        long count = cities.stream()
            .filter(c -> c.startsWith("M"))
            .count();
        System.out.println("Cities starting with M: " + count);
    }
}

